<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Problemstellen – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1050px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:22px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}.item{border:1px solid #e1e7ed;border-radius:10px;padding:14px}.message,.error{padding:12px;border-radius:9px;margin-bottom:12px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}label{display:block;font-weight:650;margin:8px 0 4px}input{width:100%;box-sizing:border-box;padding:10px;border:1px solid #bac5d1;border-radius:8px}button,.button{display:inline-block;padding:10px 14px;border:0;border-radius:9px;background:#172033;color:white;text-decoration:none;font-weight:700;margin-top:10px}.muted{color:#66758a}</style></head><body><main>
<p><a href="/dashboard">Dashboard</a> · <a href="/map">Karte</a> · <a href="/analytics">Analytics</a></p><h1>Meine Problemstellen</h1>
<?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Neue Problemstelle</h2><form method="post" action="/problem-areas"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="source" value="MANUAL"><div class="grid"><div><label>Name</label><input name="name" required></div><div><label>Breitengrad</label><input name="latitude" type="number" step="0.0000001" required></div><div><label>Längengrad</label><input name="longitude" type="number" step="0.0000001" required></div><div><label>Radius Meter</label><input name="radius_m" type="number" min="25" max="5000" value="150"></div><div><label>Ort optional</label><input name="city"></div><div><label>Straße optional</label><input name="street"></div></div><button type="submit">Problemstelle anlegen</button></form></section>
<section class="card"><h2>Private Hotspot-Vorschläge</h2><?php if(!$hotspots):?><p class="muted">Noch keine Cluster mit mindestens zwei eigenen Vorgängen.</p><?php endif;?><?php foreach($hotspots as $h):?><div class="item"><strong><?= $e($h['case_count']) ?> eigene Vorgänge</strong><p><?= $e(trim(($h['street']??'').' '.($h['city']??''))) ?></p><small><?= $e($h['latitude']) ?> / <?= $e($h['longitude']) ?></small></div><?php endforeach;?></section>
<section class="card"><h2>Gespeicherte Problemstellen</h2><div class="grid"><?php foreach($areas as $a):?><a class="item" href="/problem-areas/<?= rawurlencode($a['id']) ?>" style="color:inherit;text-decoration:none"><strong><?= $e($a['name']) ?></strong><p><?= $e($a['case_count']) ?> eigene Vorgänge · Radius <?= $e($a['radius_m']) ?> m</p><small class="muted"><?= $e($a['status']) ?> · <?= $e(trim(($a['street']??'').' '.($a['city']??''))) ?></small></a><?php endforeach;?></div></section>
</main></body></html>